// MCP Tools — the stdio JSON-RPC/MCP server (mcp/src/technocore_mcp/) that fronts a
// technocore-chat instance as WebMCP tools for a runtime that has no general HTTP fetch.
//
// This component has almost no domain state of its own: every write it can cause (a room
// message, a note) is modeled by its dependencies (quint-specs/rooms.qnt,
// quint-specs/notes-store.qnt). What THIS spec grounds is the translation layer between them —
// JSON-RPC message dispatch (protocol.py's `Server.handle`), schema-derived argument
// validation (`_validate`), the per-tool local guards server.py adds on top (say's empty-nick
// check, wait_for_message's one-sided clamp, write_note's if_absent/if_matches precedence),
// and the two-channel error model: a caller's own malformed input is a JSON-RPC `error` and
// never reaches the network; anything downstream of a validated call (a local guard, the
// remote HTTP call itself) is a tool `result` with `isError`, never a JSON-RPC error
// (protocol.py:216-229, 352-360).
//
// The remote HTTP call (`_fetch`) is modeled as one nondet `RemoteOutcome` pick per tool
// call — this component owns none of the remote service's own validation (room-name format,
// capacity, gates), so its outcome is exactly the four ways `_fetch` collapses a response:
// success, an HTTPError with a body, an HTTPError with no body (falls back to "HTTP {code}"),
// or a URLError (unreachable).
//
// Two DOCUMENTED-BUT-UNENFORCED preconditions are modeled as guard conjuncts even though the
// code's body never checks them (quint-spec-agent's rule: an unenforced documented
// precondition is still modeled, as a guard — the code taking the forbidden transition then
// surfaces as a replay violation finding, not something to refine away):
//   - `Room = Annotated[str, "Room name, ^[a-z0-9][a-z0-9_-]{0,47}$"]` (server.py:100) is
//     advertised in every room-taking tool's inputSchema but never checked locally — a
//     malformed room name round-trips to the remote service and comes back as its own isError
//     text (component-map adversary row).
//   - wait_for_message's `seconds` is documented "0-{WAIT_CEILING}" but only clamped from
//     ABOVE (`min(seconds, WAIT_CEILING)`, server.py:131) — a negative value passes straight
//     through unclamped (component-map adversary row).
module mcp_webmcp_tools {
  import basicSpells.* from "./spells/basicSpells"

  // --------------------------------------------------------------------- constants / domains

  pure val PARSE_ERROR = -32700
  pure val INVALID_REQUEST = -32600
  pure val METHOD_NOT_FOUND = -32601
  pure val INVALID_PARAMS = -32602
  pure val INTERNAL_ERROR = -32603

  pure val WAIT_CEILING = 10
  pure val DEFAULT_NICK_VALUE = "botnick"   // stand-in for a configured $TECHNOCORE_NICK

  pure val SUPPORTED_VERSIONS: Set[str] = Set("2025-06-18", "2025-03-26", "2024-11-05")
  pure val LATEST_VERSION = "2025-06-18"
  pure val ASKED_VERSIONS: Set[str] = SUPPORTED_VERSIONS.union(Set("1999-01-01"))

  // Room names: two well-formed ("lobby", "meta") and one that fails the documented
  // ^[a-z0-9][a-z0-9_-]{0,47}$ regex ("Not A Room", the exact value tests/test_mcp.py:475
  // drives) — kept in the domain so the (unenforced) precondition conjunct is falsifiable.
  pure val ROOMS: Set[str] = Set("lobby", "meta", "Not A Room")
  pure val WELLFORMED_ROOMS: Set[str] = Set("lobby", "meta")

  pure val NAMESPACES: Set[str] = Set("plans", "l")
  pure val NOTE_KEYS: Set[str] = Set("next", "k")
  pure val NOTE_VALUES: Set[str] = Set("ship it", "a", "b")
  pure val IF_MATCHES_VALUES: Set[Option[str]] = Set(None, Some("stale"), Some("ship it"))

  pure val TEXTS: Set[str] = Set("hello world", "a/b?c#d&e f")
  // Empty, a plain nick, and a whitespace-only nick — "   ".strip() is also empty, but Python's
  // `nick or DEFAULT_NICK` only falls back on the literally-empty string, not on whitespace
  // (server.py:147); both blank cases must stay distinguishable in the domain.
  pure val NICKS: Set[str] = Set("alice", "bot", "", "   ")
  pure val BOOLS: Set[bool] = Set(true, false)

  pure val SINCE_OPTS: Set[Option[int]] = Set(None, Some(0), Some(2))
  pure val LIMIT_OPTS: Set[Option[int]] = Set(None, Some(50))
  // Negative (falsifies the unenforced floor), zero, within range, and past the ceiling.
  pure val WAIT_SECONDS: Set[int] = Set(-1, 0, 5, 3600)

  pure val PAGES: Set[str] = Set("manual", "patterns", "skill")

  type ToolName =
    TReadRoom | TWaitForMessage | TSay | TListRooms | TDiscoverRooms
    | TReadNote | TWriteNote | TListNotes | TReadDocs
  pure val TOOLS: Set[ToolName] =
    Set(TReadRoom, TWaitForMessage, TSay, TListRooms, TDiscoverRooms,
        TReadNote, TWriteNote, TListNotes, TReadDocs)

  // The six ways `_validate` (protocol.py:215) rejects a tools/call, in the code's own check
  // order (unexpected key -> missing required -> per-value type -> enum) plus the two ways an
  // integer-typed argument's JSON float form is handled (protocol.py:242-243). `1.0` (an
  // integral float) is NOT here — it narrows and succeeds, modeled by
  // tools_call_float_narrowed below, not by a rejection.
  type RejectShape = ExtraKey | MissingRequired | WrongType | BadEnum | FloatFractional | BoolAsInt
  pure val REJECT_SHAPES: Set[RejectShape] =
    Set(ExtraKey, MissingRequired, WrongType, BadEnum, FloatFractional, BoolAsInt)

  type RemoteOutcome = RemoteOk | HttpErrWithBody | HttpErrEmptyBody | Unreachable
  pure val REMOTE_OUTCOMES: Set[RemoteOutcome] =
    Set(RemoteOk, HttpErrWithBody, HttpErrEmptyBody, Unreachable)

  // --------------------------------------------------------------------- state shape

  // Whether a reply-worthy request even carried a usable id (protocol.py:115-121, 305-311).
  // IdAbsent -> no `id` key at all -> a notification, never answered. IdInvalid -> an `id` key
  // whose value is not a bare str/int (null, bool, float, list, dict) -> answered with
  // INVALID_REQUEST and a null id. IdValid -> everything else.
  type IdShape = IdAbsent | IdValid | IdInvalid

  // The outbound HTTP request this step built, as structured data (never a joined string) so
  // "every caller value becomes exactly one path element, never extra path or a query string"
  // is a structural fact of the record rather than something string ops would have to check.
  type Url = {
    path: List[str],
    since: Option[int],
    limit: Option[int],
    wait: Option[int],
    ifAbsent: bool,
    ifCond: Option[str],
  }

  // Why a request got no `result`: RNone for anything that isn't a caller-input rejection.
  // Exists purely so observations can tell rejection causes apart — `handle`/`_call` only ever
  // return the numeric JSON-RPC code, which collapses e.g. "unknown tool" and "bad arg shape"
  // into the same INVALID_PARAMS the real client sees.
  type RejectReason =
    RNone | RBadId | RMissingMethod | RParamsNotObject | RUnknownMethod
    | RBadCallShape | RUnknownTool | RBadArgs(RejectShape)

  type Outcome =
    | NoReplySent                  // a notification: no `id` key, never answered
    | ProtocolError(int)           // JSON-RPC `error`: the caller's own mistake
    | HandshakeOk(str)             // `initialize` succeeded; the negotiated protocolVersion
    | PingOk
    | ToolsListOk
    | ToolResultOk(ToolName)       // a tool ran; isError: false
    | ToolResultError(ToolName)    // a tool ran; isError: true (a local guard or the remote call)

  type State = {
    outcome: Outcome,
    url: Option[Url],
    lastIdShape: IdShape,
    lastRejectReason: RejectReason,
    everInitialized: bool,
    toolRanBeforeInitialize: bool,     // ghost: a tool succeeded/failed with no prior initialize
    paramsCoercedAndDispatched: bool,  // ghost: a falsy non-object params silently became {}
    bothWriteNoteGuardsSupplied: bool, // ghost: if_absent=true seen together with if_matches
    waitClampedFromAbove: bool,        // ghost: seconds > WAIT_CEILING was clamped down
    everFloatNarrowed: bool,           // ghost: an integral float (1.0) narrowed and succeeded
    stepped: bool,                     // diagnostic latch, not a tracked observation
  }

  var state: State

  action init = all {
    state' = {
      outcome: NoReplySent,
      url: None,
      lastIdShape: IdAbsent,
      lastRejectReason: RNone,
      everInitialized: false,
      toolRanBeforeInitialize: false,
      paramsCoercedAndDispatched: false,
      bothWriteNoteGuardsSupplied: false,
      waitClampedFromAbove: false,
      everFloatNarrowed: false,
      stepped: false,
    },
  }

  // --------------------------------------------------------------------- pure logic

  pure def urlFor(path: List[str], since: Option[int], limit: Option[int], wait: Option[int],
                   ifAbsent: bool, ifCond: Option[str]): Url =
    { path: path, since: since, limit: limit, wait: wait, ifAbsent: ifAbsent, ifCond: ifCond }

  pure def noQueryUrl(path: List[str]): Url = urlFor(path, None, None, None, false, None)

  // _fetch's failure collapse (server.py:70-89): success returns the body text, an HTTPError
  // becomes RuntimeError(body-or-"HTTP {code}"), a URLError becomes RuntimeError("cannot
  // reach ..."). Every one of those three failure shapes is caught by _call (protocol.py:352)
  // and reported as isError, never as a JSON-RPC error — collapsed here to Ok/Error since none
  // of them changes this component's own state differently from another.
  pure def remoteToOutcome(tool: ToolName, remote: RemoteOutcome): Outcome =
    if (remote == RemoteOk) ToolResultOk(tool) else ToolResultError(tool)

  // "   ".strip() == "" too, but `nick or DEFAULT_NICK` (server.py:147) only falls back on the
  // literally-empty string — a whitespace-only nick is truthy in Python and is kept, then
  // strips to blank and still raises. Both paths land on "blank", by different routes.
  pure def isBlankNick(s: str): bool = s == "" or s == "   "
  pure def whoBlank(nick: str, defaultConfigured: bool): bool =
    if (nick == "") not(defaultConfigured) else isBlankNick(nick)
  pure def resolvedWho(nick: str): str = if (nick != "") nick else DEFAULT_NICK_VALUE

  pure def clampSecondsAbove(seconds: int): int = if (seconds > WAIT_CEILING) WAIT_CEILING else seconds

  // note_write's if_absent/if_matches precedence (server.py:201-204): `elif`, not two
  // independent conjuncts — if both are supplied, if_absent wins and if_matches is dropped
  // entirely, with no error and no signal to the caller. Modeled exactly as written, bug
  // included: this is a component-map adversary row, not something to "fix" here.
  pure def writeNoteGuardFields(ifAbsent: bool, ifMatches: Option[str]): (bool, Option[str]) =
    if (ifAbsent) (true, None) else (false, ifMatches)

  pure def pagePath(page: str): List[str] =
    if (page == "manual") List("llms.txt")
    else if (page == "patterns") List("patterns.md")
    else List("skill.md")

  // --------------------------------------------------------------------- envelope / dispatch actions

  // No `id` key at all: never answered, whatever the method would have been — `handle` returns
  // None before it even looks at `method` (protocol.py:305-306).
  action env_notification: bool = all {
    state' = { ...state, outcome: NoReplySent, url: None, lastIdShape: IdAbsent,
               lastRejectReason: RNone, stepped: true },
  }

  // An `id` key is present but its value isn't a bare str/int (null, a bool, a float, a list,
  // a dict) — INVALID_REQUEST, replied with a null id (protocol.py:308-309, 115-121).
  action env_bad_request_id: bool = all {
    state' = { ...state, outcome: ProtocolError(INVALID_REQUEST), url: None, lastIdShape: IdInvalid,
               lastRejectReason: RBadId, stepped: true },
  }

  // id is usable, but `method` is missing or not a string (protocol.py:310-311).
  action env_missing_method: bool = all {
    state' = { ...state, outcome: ProtocolError(INVALID_REQUEST), url: None, lastIdShape: IdValid,
               lastRejectReason: RMissingMethod, stepped: true },
  }

  // id + method are usable, and `params` is present and TRUTHY but not an object — a nonempty
  // string, a nonzero number, `true`, or a nonempty list like `["say"]` (protocol.py:312-316,
  // exercised by tests/test_mcp.py:467-470's by-position-params case).
  action env_params_not_object: bool = all {
    state' = { ...state, outcome: ProtocolError(INVALID_PARAMS), url: None, lastIdShape: IdValid,
               lastRejectReason: RParamsNotObject, stepped: true },
  }

  // `params = message.get("params") or {}` (protocol.py:312): a FALSY non-object params value
  // — `[]`, `0`, `""`, `false` — never reaches the "params must be an object" check at all; it
  // is silently replaced with `{}` and dispatch proceeds as though no params were sent. Not in
  // the component map's adversary list; found while modeling the envelope and added there.
  // Modeled against `ping`, the simplest method whose params are always ignorable.
  action env_params_falsy_coerced: bool = all {
    state' = { ...state, outcome: PingOk, url: None, lastIdShape: IdValid,
               lastRejectReason: RNone, paramsCoercedAndDispatched: true, stepped: true },
  }

  // A well-formed request whose `method` names nothing this server implements
  // (protocol.py:318-331).
  action env_unknown_method: bool = all {
    state' = { ...state, outcome: ProtocolError(METHOD_NOT_FOUND), url: None, lastIdShape: IdValid,
               lastRejectReason: RUnknownMethod, stepped: true },
  }

  // method = tools/call, but its own params shape is bad: `name` missing/not a string, or
  // `arguments` present and neither an object nor null (protocol.py:134-138, 346-347).
  action env_bad_call_shape: bool = all {
    state' = { ...state, outcome: ProtocolError(INVALID_PARAMS), url: None, lastIdShape: IdValid,
               lastRejectReason: RBadCallShape, stepped: true },
  }

  // method = tools/call, call-shape is fine, but `name` isn't one of the nine registered tools
  // — INVALID_PARAMS, not METHOD_NOT_FOUND (protocol.py:348-350; component-map adversary row,
  // confirmed at tests/test_mcp.py:394-395).
  action env_unknown_tool: bool = all {
    state' = { ...state, outcome: ProtocolError(INVALID_PARAMS), url: None, lastIdShape: IdValid,
               lastRejectReason: RUnknownTool, stepped: true },
  }

  // A known tool, but `_validate` rejects the arguments before the handler or the network is
  // ever reached (protocol.py:215-251, 351). `tool` only labels which tool was targeted; the
  // rejection itself is generic across all nine (component-map adversary surface: type/shape
  // errors are the caller's mistake, so this is always INVALID_PARAMS).
  action tools_call_bad_args(tool: ToolName, shape: RejectShape): bool = all {
    state' = { ...state, outcome: ProtocolError(INVALID_PARAMS), url: None, lastIdShape: IdValid,
               lastRejectReason: RBadArgs(shape), stepped: true },
  }

  // An integer-typed argument arrives as an integral float (`1.0`) — JSON Schema reads
  // `integer` by value, so this narrows to `1` and the call proceeds normally
  // (protocol.py:242-243, tests/test_mcp.py:443-461). Generic across tools, like the rejection
  // above: which tool doesn't change that the narrowing itself succeeds.
  action tools_call_float_narrowed(tool: ToolName, remote: RemoteOutcome): bool = all {
    state' = { ...state, outcome: remoteToOutcome(tool, remote), url: Some(noQueryUrl(List("narrowed"))),
               lastIdShape: IdValid, lastRejectReason: RNone, everFloatNarrowed: true, stepped: true },
  }

  action handle_initialize(asked: str): bool = {
    val negotiated = if (SUPPORTED_VERSIONS.contains(asked)) asked else LATEST_VERSION
    all {
      state' = { ...state, outcome: HandshakeOk(negotiated), url: None, lastIdShape: IdValid,
                 lastRejectReason: RNone, everInitialized: true, stepped: true },
    }
  }

  action handle_ping: bool = all {
    state' = { ...state, outcome: PingOk, url: None, lastIdShape: IdValid,
               lastRejectReason: RNone, stepped: true },
  }

  action handle_tools_list: bool = all {
    state' = { ...state, outcome: ToolsListOk, url: None, lastIdShape: IdValid,
               lastRejectReason: RNone, stepped: true },
  }

  // --------------------------------------------------------------------- tool actions

  action tool_read_room(room: str, since: Option[int], limit: Option[int], remote: RemoteOutcome): bool = all {
    WELLFORMED_ROOMS.contains(room),   // documented Room regex, unenforced by code — see header
    state' = { ...state,
      url: Some(urlFor(List("r", room), since, limit, None, false, None)),
      outcome: remoteToOutcome(TReadRoom, remote),
      lastIdShape: IdValid, lastRejectReason: RNone,
      toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized),
      stepped: true },
  }

  action tool_wait_for_message(room: str, since: int, seconds: int, remote: RemoteOutcome): bool = {
    val effective = clampSecondsAbove(seconds)
    all {
      WELLFORMED_ROOMS.contains(room),
      seconds >= 0,   // documented "0-WAIT_CEILING" floor, unenforced by code — see header
      state' = { ...state,
        url: Some(urlFor(List("r", room), Some(since), None, Some(effective), false, None)),
        outcome: remoteToOutcome(TWaitForMessage, remote),
        lastIdShape: IdValid, lastRejectReason: RNone,
        toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized),
        waitClampedFromAbove: waitClampedFromAbove or (seconds > WAIT_CEILING),
        stepped: true },
    }
  }

  // say's own local guard (server.py:147-149): a blank resolved nick raises ValueError before
  // _fetch is ever called — that is a tool result (isError: true), never a JSON-RPC error,
  // because it is downstream of a validated call, not the caller's malformed input.
  action tool_say(room: str, text: str, nick: str, defaultConfigured: bool, remote: RemoteOutcome): bool = all {
    WELLFORMED_ROOMS.contains(room),
    state' =
      if (whoBlank(nick, defaultConfigured))
        { ...state, url: None, outcome: ToolResultError(TSay),
          lastIdShape: IdValid, lastRejectReason: RNone,
          toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized), stepped: true }
      else
        { ...state, url: Some(urlFor(List("r", room, "say", resolvedWho(nick), text), None, None, None, false, None)),
          outcome: remoteToOutcome(TSay, remote),
          lastIdShape: IdValid, lastRejectReason: RNone,
          toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized), stepped: true },
  }

  action tool_list_rooms(limit: Option[int], remote: RemoteOutcome): bool = all {
    state' = { ...state,
      url: Some(urlFor(List("rooms"), None, limit, None, false, None)),
      outcome: remoteToOutcome(TListRooms, remote),
      lastIdShape: IdValid, lastRejectReason: RNone,
      toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized),
      stepped: true },
  }

  action tool_discover_rooms(since: Option[int], remote: RemoteOutcome): bool = all {
    state' = { ...state,
      url: Some(urlFor(List("r", "events"), since, None, None, false, None)),
      outcome: remoteToOutcome(TDiscoverRooms, remote),
      lastIdShape: IdValid, lastRejectReason: RNone,
      toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized),
      stepped: true },
  }

  action tool_read_note(ns: str, key: str, remote: RemoteOutcome): bool = all {
    state' = { ...state,
      url: Some(noQueryUrl(List("kv", ns, key))),
      outcome: remoteToOutcome(TReadNote, remote),
      lastIdShape: IdValid, lastRejectReason: RNone,
      toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized),
      stepped: true },
  }

  action tool_list_notes(ns: str, remote: RemoteOutcome): bool = all {
    state' = { ...state,
      url: Some(noQueryUrl(List("kv", ns))),
      outcome: remoteToOutcome(TListNotes, remote),
      lastIdShape: IdValid, lastRejectReason: RNone,
      toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized),
      stepped: true },
  }

  action tool_write_note(ns: str, key: str, value: str, ifMatches: Option[str], ifAbsent: bool,
                          remote: RemoteOutcome): bool = {
    val fields = writeNoteGuardFields(ifAbsent, ifMatches)
    all {
      state' = { ...state,
        url: Some(urlFor(List("kv", ns, key, "set", value), None, None, None, fields._1, fields._2)),
        outcome: remoteToOutcome(TWriteNote, remote),
        lastIdShape: IdValid, lastRejectReason: RNone,
        toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized),
        bothWriteNoteGuardsSupplied: bothWriteNoteGuardsSupplied or (ifAbsent and ifMatches != None),
        stepped: true },
    }
  }

  action tool_read_docs(page: str, remote: RemoteOutcome): bool = all {
    PAGES.contains(page),
    state' = { ...state,
      url: Some(noQueryUrl(pagePath(page))),
      outcome: remoteToOutcome(TReadDocs, remote),
      lastIdShape: IdValid, lastRejectReason: RNone,
      toolRanBeforeInitialize: toolRanBeforeInitialize or not(everInitialized),
      stepped: true },
  }

  // --------------------------------------------------------------------- step

  action step = any {
    env_notification,
    env_bad_request_id,
    env_missing_method,
    env_params_not_object,
    env_params_falsy_coerced,
    env_unknown_method,
    env_bad_call_shape,
    env_unknown_tool,

    { nondet tool = TOOLS.oneOf()
      nondet shape = REJECT_SHAPES.oneOf()
      tools_call_bad_args(tool, shape) },

    { nondet tool = TOOLS.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tools_call_float_narrowed(tool, remote) },

    { nondet asked = ASKED_VERSIONS.oneOf()
      handle_initialize(asked) },

    handle_ping,
    handle_tools_list,

    { nondet room = ROOMS.oneOf()
      nondet since = SINCE_OPTS.oneOf()
      nondet limit = LIMIT_OPTS.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tool_read_room(room, since, limit, remote) },

    { nondet room = ROOMS.oneOf()
      nondet since = 0.to(2).oneOf()
      nondet seconds = WAIT_SECONDS.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tool_wait_for_message(room, since, seconds, remote) },

    { nondet room = ROOMS.oneOf()
      nondet text = TEXTS.oneOf()
      nondet nick = NICKS.oneOf()
      nondet defaultConfigured = BOOLS.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tool_say(room, text, nick, defaultConfigured, remote) },

    { nondet limit = LIMIT_OPTS.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tool_list_rooms(limit, remote) },

    { nondet since = SINCE_OPTS.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tool_discover_rooms(since, remote) },

    { nondet ns = NAMESPACES.oneOf()
      nondet key = NOTE_KEYS.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tool_read_note(ns, key, remote) },

    { nondet ns = NAMESPACES.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tool_list_notes(ns, remote) },

    { nondet ns = NAMESPACES.oneOf()
      nondet key = NOTE_KEYS.oneOf()
      nondet value = NOTE_VALUES.oneOf()
      nondet ifMatches = IF_MATCHES_VALUES.oneOf()
      nondet ifAbsent = BOOLS.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tool_write_note(ns, key, value, ifMatches, ifAbsent, remote) },

    { nondet page = PAGES.oneOf()
      nondet remote = REMOTE_OUTCOMES.oneOf()
      tool_read_docs(page, remote) },
  }

  // --------------------------------------------------------------------- properties

  /// Every outbound request this wrapper builds belongs to a tool call that actually ran.
